function Glyph({icon:Icon,size=16}:{icon:React.ElementType;size?:number}) { return <Icon size={size} weight="regular" aria-hidden="true"/>; }
function AppNav({view,onNavigate,signedIn}:{view:View;onNavigate:(v:View)=>void;signedIn:boolean}) {
  const hiringItems:[string,View,React.ElementType,View[]][]=[["Overview","overview",House,["overview"]],["Roles","roles",Briefcase,["roles","role-builder","role-rubric"]],["Candidates","candidates",ChartBar,["candidates","invites","report"]],["Compare","compare",ListChecks,["compare"]]];
  return <aside className="sidebar" aria-label="Ari workspace navigation"><div className="sidebar-brand"><button className="wordmark app-wordmark" onClick={()=>onNavigate(signedIn?"overview":"landing")} aria-label="Ari workspace home">Ari</button><span>Interview platform</span></div><nav className="sidebar-nav" aria-label="Workspace sections">{!signedIn&&<div className="nav-group"><div className="nav-label">Explore</div><button className="nav-item" onClick={()=>onNavigate("landing")}><span className="nav-icon"><Glyph icon={House}/></span><span>Home</span></button></div>}{signedIn&&<div className="nav-group"><div className="nav-label">Hiring workspace</div>{hiringItems.map(([label,target,Icon,views])=><button key={target} className={`nav-item ${views.includes(view)?"active":""}`} aria-current={views.includes(view)?"page":undefined} onClick={()=>onNavigate(target)}><span className="nav-icon"><Glyph icon={Icon}/></span><span>{label}</span></button>)}</div>}<div className="nav-group"><div className="nav-label">Your space</div><button className={`nav-item ${["practice","practice-setup","practice-report"].includes(view)?"active":""}`} aria-current={["practice","practice-setup","practice-report"].includes(view)?"page":undefined} onClick={()=>onNavigate("practice")}><span className="nav-icon"><Glyph icon={Sparkle}/></span><span>Practice</span></button>{signedIn&&<button className={`nav-item ${view==="profile"?"active":""}`} aria-current={view==="profile"?"page":undefined} onClick={()=>onNavigate("profile")}><span className="nav-icon"><Glyph icon={UserCircle}/></span><span>Profile</span></button>}</div></nav><div className="sidebar-foot"><span className="status-dot"/> Structured interviews, human decisions</div></aside>;
}
function Header({view,signedIn}:{view:View;signedIn:boolean}) { const isHiring=recruiterViews.includes(view); return <header className="topbar"><div className="topbar-context"><span className="status-dot"/>{view==="profile"?"Your profile":isHiring?"Hiring workspace":"Interview with Ari"}</div><div className="top-actions">{signedIn&&<AuthAccount/>}</div></header>; }

