  useEffect(()=>{if(!authPending&&!sessionUser&&protectedViews.includes(view)){window.location.replace(`/auth/sign-in?returnTo=${encodeURIComponent(`${window.location.pathname}?view=${view}`)}`)}},[authPending,sessionUser,view]);
