  function navigate(next:View){if(protectedViews.includes(next)&&!sessionUser){window.location.assign(`/auth/sign-in?returnTo=${encodeURIComponent(`${window.location.pathname}?view=${next}`)}`);return}if(next==="practice-setup")manualResumeSelectionRef.current=false;if(next!=="interview"){setRoomPrepared(false);setPrepareTimeout(false);}setView(next);setError("");const u=new URL(window.location.href);u.searchParams.set("view",next);window.history.pushState({},"",u);window.scrollTo({top:0,behavior:"smooth"});}
  function notify(message:string){setToastText(message);window.setTimeout(()=>setToastText(""),2800);}
